create table public.admin_emails (
  email text not null,
  note text,
  added_at timestamp with time zone default now() not null,
  owner boolean default false not null,
  added_by text,
  constraint admin_emails_pkey PRIMARY KEY (email),
  constraint admin_emails_added_by CHECK (((char_length(added_by) >= 1) AND (char_length(added_by) <= 100))),
  constraint admin_emails_email_check CHECK (((email = lower(TRIM(BOTH FROM email))) AND public.is_allowed_email(email)))
);

CREATE UNIQUE INDEX admin_emails_one_owner ON public.admin_emails USING btree (owner) WHERE owner;

alter table public.admin_emails enable row level security;

grant delete, insert, maintain, references, select, trigger, truncate, update on table public.admin_emails to service_role;
